--
-- Trạm Chữ Novel - Local PostgreSQL initialization script
-- Creates the application schema and seeds the local database.
-- Compatible with PostgreSQL versions supported by the backend.

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Name: pg_trgm; Type: EXTENSION; Schema: -; Owner: -
--

-- Drop application objects so this file can safely reinitialize a local database.
DROP TABLE IF EXISTS
  public.admin_audit_logs,
  public.bookmarks,
  public.chapters,
  public.comments,
  public.likes,
  public.notifications,
  public.ratings,
  public.reading_history,
  public.reports,
  public.site_settings,
  public.story_categories,
  public.stories,
  public.categories,
  public.authors,
  public.admins,
  public.users
CASCADE;

DROP FUNCTION IF EXISTS public.trigger_set_updated_at() CASCADE;

DROP TYPE IF EXISTS
  public.comment_status,
  public.notification_type,
  public.report_status,
  public.story_status,
  public.user_role
CASCADE;
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;

--
-- Name: EXTENSION pg_trgm; Type: COMMENT; Schema: -; Owner: 
--

COMMENT ON EXTENSION pg_trgm IS 'text similarity measurement and index searching based on trigrams';

--
-- Name: uuid-ossp; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA public;

--
-- Name: EXTENSION "uuid-ossp"; Type: COMMENT; Schema: -; Owner: 
--

COMMENT ON EXTENSION "uuid-ossp" IS 'generate universally unique identifiers (UUIDs)';

--
-- Name: comment_status; Type: TYPE; Schema: public; Owner: local
--

CREATE TYPE public.comment_status AS ENUM (
    'pending',
    'approved',
    'rejected'
);

--
-- Name: notification_type; Type: TYPE; Schema: public; Owner: local
--

CREATE TYPE public.notification_type AS ENUM (
    'new_chapter',
    'comment_reply',
    'story_approved',
    'story_rejected',
    'system',
    'report_resolved',
    'new_comment',
    'new_rating',
    'new_bookmark',
    'new_like',
    'new_report'
);

--
-- Name: report_status; Type: TYPE; Schema: public; Owner: local
--

CREATE TYPE public.report_status AS ENUM (
    'pending',
    'accepted',
    'processing',
    'resolved',
    'rejected'
);

--
-- Name: story_status; Type: TYPE; Schema: public; Owner: local
--

CREATE TYPE public.story_status AS ENUM (
    'ongoing',
    'completed'
);

--
-- Name: user_role; Type: TYPE; Schema: public; Owner: local
--

CREATE TYPE public.user_role AS ENUM (
    'reader'
);

--
-- Name: trigger_set_updated_at(); Type: FUNCTION; Schema: public; Owner: local
--

CREATE FUNCTION public.trigger_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

SET default_tablespace = '';

--
-- Name: admin_audit_logs; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.admin_audit_logs (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    admin_id character varying(50),
    action character varying(100) NOT NULL,
    target_type character varying(50) NOT NULL,
    target_id uuid NOT NULL,
    details jsonb,
    ip_address inet,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: admins; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.admins (
    id character varying(50) NOT NULL,
    username character varying(50) NOT NULL,
    email character varying(255) NOT NULL,
    password character varying(255) NOT NULL,
    avatar_url text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_login_at timestamp with time zone
);

--
-- Name: authors; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.authors (
    id character varying(50) NOT NULL,
    pen_name character varying(100) NOT NULL,
    email character varying(255) NOT NULL,
    password character varying(255) NOT NULL,
    avatar_url text,
    bio text,
    donation_link text,
    total_views bigint DEFAULT 0 NOT NULL,
    is_banned boolean DEFAULT false NOT NULL,
    banned_at timestamp with time zone,
    ban_reason text,
    last_login_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: bookmarks; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.bookmarks (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id character varying(50) NOT NULL,
    story_id character varying(50) NOT NULL,
    last_read_chapter integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: categories; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.categories (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    name character varying(100) NOT NULL,
    slug character varying(100) NOT NULL
);

--
-- Name: chapters; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.chapters (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    story_id character varying(50) NOT NULL,
    chapter_number integer NOT NULL,
    title character varying(300) NOT NULL,
    content text NOT NULL,
    word_count integer DEFAULT 0 NOT NULL,
    view_count bigint DEFAULT 0 NOT NULL,
    is_published boolean DEFAULT true NOT NULL,
    password character varying(100) DEFAULT NULL::character varying,
    password_question character varying(255) DEFAULT NULL::character varying,
    password_hint character varying(255) DEFAULT NULL::character varying,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    scheduled_at timestamp with time zone
);

--
-- Name: comments; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.comments (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id character varying(50),
    author_id character varying(50),
    story_id character varying(50) NOT NULL,
    chapter_id uuid,
    parent_id uuid,
    content text NOT NULL,
    status public.comment_status DEFAULT 'approved'::public.comment_status NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_comment_owner CHECK ((((user_id IS NOT NULL) AND (author_id IS NULL)) OR ((user_id IS NULL) AND (author_id IS NOT NULL))))
);

--
-- Name: likes; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.likes (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id character varying(50) NOT NULL,
    story_id character varying(50) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: notifications; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.notifications (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id character varying(50),
    author_id character varying(50),
    type public.notification_type NOT NULL,
    title character varying(200) NOT NULL,
    message text NOT NULL,
    link text,
    is_read boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_notification_owner CHECK ((((user_id IS NOT NULL) AND (author_id IS NULL)) OR ((user_id IS NULL) AND (author_id IS NOT NULL)) OR ((user_id IS NULL) AND (author_id IS NULL))))
);

--
-- Name: ratings; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.ratings (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id character varying(50) NOT NULL,
    story_id character varying(50) NOT NULL,
    score smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ratings_score_check CHECK (((score >= 1) AND (score <= 5)))
);

--
-- Name: reading_history; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.reading_history (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id character varying(50),
    story_id character varying(50) NOT NULL,
    chapter_id uuid,
    read_at timestamp with time zone DEFAULT now() NOT NULL,
    ip_address inet,
    user_agent text
);

--
-- Name: reports; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.reports (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id character varying(50),
    story_id character varying(50),
    comment_id uuid,
    reason text NOT NULL,
    status public.report_status DEFAULT 'pending'::public.report_status NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: site_settings; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.site_settings (
    key character varying(100) NOT NULL,
    value text NOT NULL,
    description text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by character varying(50)
);

--
-- Name: stories; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.stories (
    id character varying(50) NOT NULL,
    author_id character varying(50) NOT NULL,
    category_id uuid,
    title character varying(300) NOT NULL,
    slug character varying(350) NOT NULL,
    cover_image text,
    description text,
    status public.story_status DEFAULT 'ongoing'::public.story_status NOT NULL,
    view_count bigint DEFAULT 0 NOT NULL,
    rating numeric(3,2) DEFAULT 0.00 NOT NULL,
    chapter_count integer DEFAULT 0 NOT NULL,
    like_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: story_categories; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.story_categories (
    story_id character varying(50) NOT NULL,
    category_id uuid NOT NULL
);

--
-- Name: users; Type: TABLE; Schema: public; Owner: local
--

CREATE TABLE public.users (
    id character varying(50) NOT NULL,
    username character varying(50) NOT NULL,
    display_name character varying(100),
    email character varying(255) NOT NULL,
    password character varying(255) NOT NULL,
    role public.user_role DEFAULT 'reader'::public.user_role NOT NULL,
    avatar_url text,
    is_banned boolean DEFAULT false NOT NULL,
    banned_at timestamp with time zone,
    ban_reason text,
    can_comment boolean DEFAULT true NOT NULL,
    last_login_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

